private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null for rotation");
    }
    TreeNode<T> left = node.getLeft();
    if (left == null) {
        throw new IllegalArgumentException("Cannot rotate right: left child is null");
    }
    TreeNode<T> leftRight = left.getRight();

    // Perform rotation
    left.setRight(node);
    node.setLeft(leftRight);

    // Update parent references if they exist
    TreeNode<T> parent = node.getParent();
    left.setParent(parent);
    if (parent != null) {
        if (parent.getLeft() == node) {
            parent.setLeft(left);
        } else if (parent.getRight() == node) {
            parent.setRight(left);
        }
    }
    node.setParent(left);
    if (leftRight != null) {
        leftRight.setParent(node);
    }

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if(node == null || node.left == null){
        return node;
    }
    TreeNode<T> leftChild = node.left;
    node.left = leftChild.right;
    leftChild.right = node;
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Validate input
    if (node == null || node.left == null) {
        return node; // nothing to rotate
    }

    TreeNode<T> newRoot = node.left;

    // Detach newRoot's right child and attach to node
    node.left = newRoot.right;
    if (newRoot.right != null) {
        newRoot.right.parent = node;
    }

    // Connect newRoot to node's parent
    newRoot.parent = node.parent;
    if (node.parent != null) {
        if (node.parent.left == node) {
            node.parent.left = newRoot;
        } else if (node.parent.right == node) {
            node.parent.right = newRoot;
        }
    }

    // Make node the right child of newRoot
    newRoot.right = node;
    node.parent = newRoot;

    return newRoot;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }

    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        // Nothing to rotate
        return node;
    }

    // Rotate: leftChild becomes new root of this subtree
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }

    leftChild.right = node;
    leftChild.parent = node.parent;
    node.parent = leftChild;

    // Update the parent link of the old node’s parent (if any)
    if (leftChild.parent != null) {
        if (leftChild.parent.left == node) {
            leftChild.parent.left = leftChild;
        } else if (leftChild.parent.right == node) {
            leftChild.parent.right = leftChild;
        }
    }

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        throw new IllegalArgumentException("node has no left child to perform a right rotation");
    }
    try {
        // Detach left child's right subtree and attach it to node's left
        node.left = leftChild.right;
        if (node.left != null) {
            node.left.parent = node; // update parent link if it exists
        }

        // Place node as the right child of its former left child
        leftChild.right = node;
        leftChild.parent = node.parent; // updated parent link
        node.parent = leftChild;

        return leftChild;
    } catch (Exception e) {
        throw new RuntimeException("Right rotation failed", e);
    }
}

