        throw new NullPointerException("file");
    }
    if (!file.exists()) {
        // Nothing to schedule
        return;
    }
    scheduleRecursively(file);
}

private static void scheduleRecursively(File f) throws IOException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children == null) {
            // This can happen if an I/O error occurs or if f is not a directory
            if (!f.isDirectory()) {
                // f is a regular file; just schedule it
                f.deleteOnExit();
                return;
            }
            throw new IOException("Unable to list contents of directory: " + f);
        }
        for (File child : children) {
            scheduleRecursively(child);
        }
    }
    f.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    try {
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children != null) {
                for (File child : children) {
                    forceDeleteOnExit(child);
                }
            }
        }
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Failed to schedule deletion for " + file, e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    java.util.Deque<File> stack = new java.util.ArrayDeque<>();
    java.util.Deque<File> order = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        order.push(current);
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children == null) {
                throw new IOException("Failed to list contents of directory: " + current);
            }
            for (File child : children) {
                stack.push(child);
            }
        }
    }
    while (!order.isEmpty()) {
        File f = order.pop();
        try {
            f.deleteOnExit();
        } catch (SecurityException se) {
            throw new IOException("Unable to schedule deletion for: " + f, se);
        }
    }
}

