public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("Message cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new NullPointerException("LinkedBuffer cannot be null");
    }

    int size = schema.getSerializedSize(message, buffer);
    if (size < 0) {
        throw new IOException("Calculated message size is negative: " + size);
    }

    // Write size as a varint
    int value = size;
    while ((value & ~0x7F) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value);

    // Write the actual message
    schema.writeTo(message, out, buffer);

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
