    }
    if (schema == null) {
        throw new NullPointerException("Schema is null");
    }

    // Determine the serialized size of the message.
    int size = schema.getCachedSize(message);

    // Write the size as a varint32 prefix.
    writeRawVarint32(out, size);

    // Write the message itself to the OutputStream.
    schema.writeTo(message, out);

    return size;
}

/**
 * Writes a 32‑bit integer using the Protocol Buffers varint encoding.
 */
private static void writeRawVarint32(OutputStream out, int value) throws IOException {
    while ((value & 0xFFFFFF80) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value);
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("Output stream must not be null");
    }
    if (message == null) {
        throw new NullPointerException("Message must not be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema must not be null");
    }
    if (buffer == null) {
        throw new NullPointerException("LinkedBuffer must not be null");
    }

    // The size of the serialized message.
    int size = schema.getCachedSize(message);

    // Use a CodedOutputStream to write the size as a varint and then the message itself.
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    schema.serializeTo(cos, message, buffer);
    // `cos` will flush its internal buffer to `out` automatically when needed.
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("Output stream is null");
    }
    if (message == null) {
        throw new NullPointerException("Message is null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema is null");
    }
    if (buffer == null) {
        buffer = LinkedBuffer.allocate(512); // default size if buffer not supplied
    }

    // Get the size of the serialized message
    int msgSize = schema.getSerializedSize(message, buffer);

    // Write the size as a varint prefix to the output stream
    int tempSize = msgSize;
    while ((tempSize & ~0x7F) != 0) {
        out.write((tempSize & 0x7F) | 0x80);
        tempSize >>>= 7;
    }
    out.write(tempSize);

    // Serialize the actual message to the output stream
    try {
        schema.writeTo(out, message, buffer);
    } catch (IOException e) {
        // If serialization fails, rethrow the IOException
        throw e;
    }

    return msgSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    // Calculate the size of the serialized message
    int size = schema.getSerializedSize(message);
    // Create a CodedOutputStream on top of the provided OutputStream
    com.google.protobuf.CodedOutputStream cos = com.google.protobuf.CodedOutputStream.newInstance(out);
    // Write the length prefix (encoded as a varint)
    cos.writeRawVarint32(size);
    // Write the message itself
    schema.writeTo(message, cos);
    // Flush to ensure all data is written out
    cos.flush();
    return size;
}

