public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Validate inputs
    if (genericType == null || targetType == null) {
        return null;
    }
    // Must be a ParameterizedType to resolve arguments
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    try {
        ParameterizedType ptGeneric = (ParameterizedType) genericType;
        Class<?> rawGeneric = (Class<?>) ptGeneric.getRawType();
        // Find a ParameterizedType in targetType hierarchy that matches the raw generic type
        ParameterizedType ptTarget = findParameterizedType(targetType, rawGeneric);
        if (ptTarget == null) {
            return null;
        }
        // Map type variables of rawGeneric to actual types from the target's ParameterizedType
        TypeVariable<?>[] rawTypeVariables = rawGeneric.getTypeParameters();
        Type[] targetActuals = ptTarget.getActualTypeArguments();
        if (rawTypeVariables.length != targetActuals.length) {
            return null;
        }
        Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
        for (int i = 0; i < rawTypeVariables.length; i++) {
            typeVarMap.put(rawTypeVariables[i], targetActuals[i]);
        }
        // Resolve each argument of the genericType
        Type[] genericArgs = ptGeneric.getActualTypeArguments();
        Class<?>[] result = new Class<?>[genericArgs.length];
        for (int i = 0; i < genericArgs.length; i++) {
            Type arg = genericArgs[i];
            if (arg instanceof Class<?>) {
                result[i] = (Class<?>) arg;
            } else if (arg instanceof ParameterizedType) {
                // For nested parameterized types, return the raw type
                result[i] = (Class<?>) ((ParameterizedType) arg).getRawType();
            } else if (arg instanceof TypeVariable<?>) {
                Type actual = typeVarMap.get(arg);
                if (actual instanceof Class<?>) {
                    result[i] = (Class<?>) actual;
                } else if (actual instanceof ParameterizedType) {
                    result[i] = (Class<?>) ((ParameterizedType) actual).getRawType();
                } else {
                    // Cannot resolve wildcard or other type variable
                    return null;
                }
            } else {
                // WildcardType, GenericArrayType, etc. are not resolved
                return null;
            }
        }
        return result;
    } catch (Exception e) {
        // Any unexpected exception results in null as per spec
        return null;
    }
}

/**
 * Recursively searches the class hierarchy of {@code clazz} for a {@link ParameterizedType}
 * whose raw type equals {@code targetRaw}. Returns {@code null} if none is found.
 */
private static ParameterizedType findParameterizedType(Class<?> clazz, Class<?> targetRaw) {
    if (clazz == null || clazz == Object.class) {
        return null;
    }
    // Check superclass
    Type superType = clazz.getGenericSuperclass();
    if (superType instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) superType;
        Class<?> raw = (Class<?>) pt.getRawType();
        if (raw.equals(targetRaw)) {
            return pt;
        }
    }
    // Check interfaces
    for (Type iface : clazz.getGenericInterfaces()) {
        if (iface instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) iface;
            Class<?> raw = (Class<?>) pt.getRawType();
            if (raw.equals(targetRaw)) {
                return pt;
            }
        }
    }
    // Recurse up the hierarchy
    return findParameterizedType(clazz.getSuperclass(), targetRaw);
}

@Override
public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    try {
        // Determine a key for caching; we assume METRICS class exposes a getKey() or toString() method.
        String key;
        try {
            // Try a dedicated key method first
            java.lang.reflect.Method getKeyMethod = METRICS.class.getMethod("getKey");
            key = (String) getKeyMethod.invoke(data);
        } catch (NoSuchMethodException | IllegalAccessException | IllegalArgumentException | java.lang.reflect.InvocationTargetException e) {
            // Fallback to using the object's hash code as a key
            key = String.valueOf(data.hashCode());
        }
        if (key == null || key.isEmpty()) {
            return;
        }

        METRICS existing = cache.get(key);
        if (existing == null) {
            cache.put(key, data);
        } else {
            // Attempt to merge existing with new data using a merge method if present
            try {
                java.lang.reflect.Method mergeMethod = METRICS.class.getMethod("merge", METRICS.class);
                // Merge in-place
                mergeMethod.invoke(existing, data);
            } catch (NoSuchMethodException | IllegalAccessException | IllegalArgumentException | java.lang.reflect.InvocationTargetException e) {
                // If merge method is not available or fails, replace the old value
                cache.put(key, data);
            }
        }
    } catch (Exception e) {
        // In a real scenario you might want to log this exception.
        // For safety we just swallow exceptions to avoid disrupting the caller.
    }
}

