        // The key could simply be the metric itself if its equals/hashCode are correctly implemented.
        METRICS existing = metricsCache.get(data);

        if (existing != null) {
            // Merge the incoming metric with the existing one.
            // The METRICS type should expose a mergeWith method that returns a new merged instance.
            METRICS merged = null;
            try {
                // Preferred: use a defined mergeWith method
                merged = data.mergeWith(existing);
            } catch (NoSuchMethodError | UnsupportedOperationException e) {
                // Fallback: if mergeWith is not available, replace the existing entry
                merged = data;
            }
            metricsCache.put(data, merged);
        } else {
            // No existing entry – simply cache the new metric
            metricsCache.put(data, data);
        }
    } catch (Exception e) {
        // Log or wrap exception – here we wrap in a RuntimeException to surface the error
        throw new RuntimeException("Unable to accept METRICS during cache merge", e);
