@Override public void accept(final METRICS data) {
    if (data == null) {
        return; // nothing to merge
    }
    try {
        // Merge the incoming metric into the cache.
        // The "cache" map is assumed to exist in the surrounding class and
        // uses METRICS objects as both key and value. If an entry already exists,
        // we attempt to merge it via a 'merge' method defined on METRICS.
        cache.merge(data, data, (existing, incoming) -> {
            try {
                java.lang.reflect.Method mergeMethod = METRICS.class.getMethod("merge", METRICS.class);
                mergeMethod.invoke(existing, incoming);
                return existing;
            } catch (Exception e) {
                // Fallback: replace the existing value if merge is not available
                return incoming;
            }
        });
