@Override
public void accept(final METRICS data){
    if (data == null) {
        return;
    }
    try {
        /* Try to obtain a key and a numeric value via reflection.  If the metric does not expose these
         * methods we fall back to a simple cache entry using the metric's toString(). */
        java.lang.reflect.Method keyMethod = data.getClass().getMethod("getKey");
        java.lang.reflect.Method valueMethod = data.getClass().getMethod("getValue");
        String key = (String) keyMethod.invoke(data);
        Number number = (Number) valueMethod.invoke(data);
        if (key == null) {
            key = data.toString();
        }
        if (number == null) {
            number = 1L;
        }

        @SuppressWarnings("unchecked")
        java.util.Map<String, Number> m = (java.util.Map<String, Number>) cache;
        Number existing = m.get(key);
        if (existing == null) {
            m.put(key, number);
        } else {
            long sum = existing.longValue() + number.longValue();
            m.put(key, sum);
        }
    } catch (NoSuchMethodException e) {
        /* The metric does not have getKey()/getValue().  Use the metric's string form as the key and
         * increment a counter value. */
        String key = data.toString();
        @SuppressWarnings("unchecked")
        java.util.Map<String, Number> m = (java.util.Map<String, Number>) cache;
        Number existing = m.get(key);
        if (existing == null) {
            m.put(key, 1L);
        } else {
            m.put(key, existing.longValue() + 1L);
        }
    } catch (Exception e) {
        /* If anything unexpected occurs we store the metric object itself keyed by its toString()
         * representation.  This ensures the cache never loses the data due to an unhandled error. */
        @SuppressWarnings("unchecked")
        java.util.Map<String, Object> m = (java.util.Map<String, Object>) cache;
        m.put(data.toString(), data);
    }
}

void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    try {
        // Link this bucket into the list before the given bucket
        this.next = bucket;
        this.prev = bucket.prev;

        if (bucket.prev != null) {
            bucket.prev.next = this;
        }
        bucket.prev = this;
    } catch (Exception e) {
        throw new RuntimeException("Failed to insert bucket", e);
    }
}

