        File home = new File(userHome);
        File parent = home.getParentFile();
        if (parent != null) {
            configDir = new File(parent, "lf5");
        } else {
            configDir = new File(userHome, "lf5");
        }
    } else {
        configDir = new File(userHome, "lf5");
