    if (str == null) {
        throw new NullPointerException("String argument is null");
    }
    int end = index + len;
    if (index < 0 || len < 0 || end > str.length()) {
        throw new IndexOutOfBoundsException(
            "index: " + index + ", length: " + len + ", str.length(): " + str.length());
    }

    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (ch >= 0xD800 && ch <= 0xDBFF) { // high surrogate
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) { // valid surrogate pair
                    size += 4;
                    i++; // skip low surrogate
                } else {
                    size += 3; // treat high surrogate as 3-byte sequence
                }
            } else {
                size += 3; // high surrogate at end
            }
        } else {
            // low surrogate or non-ASCII BMP character
            size += 3;
        }
    }
    return size;
}

