public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("Input string is null");
    }
    if (index < 0 || len < 0 || (long) index + len > str.length()) {
        throw new IndexOutOfBoundsException("index and/or length are out of bounds");
    }
    int utf8Size = 0;
    int i = index;
    int remaining = len;
    while (remaining > 0) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch) && remaining > 1) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                // Surrogate pair – encodes as a single code point (4 bytes)
                utf8Size += 4;
                i += 2;
                remaining -= 2;
                continue;
            }
            // Malformed surrogate – treat high surrogate as a standalone char
        }
        int codePoint = (int) ch;
        if (codePoint <= 0x7F) {
            utf8Size += 1;
        } else if (codePoint <= 0x7FF) {
            utf8Size += 2;
        } else { // 0x800–0xFFFF
            utf8Size += 3;
        }
        i++;
        remaining--;
    }
    return utf8Size;
}

