private Set<V> initVisibleVertices(){
    Set<V> vertices = new HashSet<>();
    if (edges == null) return vertices; // no edges, no visible vertices
    for (Object e : edges) {
        if (e == null) continue;
        try {
            // First try the common method names
            var sourceMethod = e.getClass().getMethod("getSource");
            var targetMethod = e.getClass().getMethod("getTarget");
            @SuppressWarnings("unchecked")
            V source = (V) sourceMethod.invoke(e);
            @SuppressWarnings("unchecked")
            V target = (V) targetMethod.invoke(e);
            if (source != null) vertices.add(source);
            if (target != null) vertices.add(target);
            continue;
        } catch (Exception ignored) {
            // fall back to alternative method names
        }
        try {
            var fromMethod = e.getClass().getMethod("getFrom");
            var toMethod = e.getClass().getMethod("getTo");
            @SuppressWarnings("unchecked")
            V from = (V) fromMethod.invoke(e);
            @SuppressWarnings("unchecked")
            V to = (V) toMethod.invoke(e);
            if (from != null) vertices.add(from);
            if (to != null) vertices.add(to);
            continue;
        } catch (Exception ignored) {
            // continue to next fallback
        }
        // Very generic fallback: collect entries if edge is a collection or array
        try {
            if (e instanceof Collection) {
                for (Object obj : (Collection<?>) e) {
                    if (obj instanceof V) vertices.add((V) obj);
                }
            } else if (e.getClass().isArray()) {
                int len = java.lang.reflect.Array.getLength(e);
                for (int i = 0; i < len; i++) {
                    Object obj = java.lang.reflect.Array.get(e, i);
                    if (obj instanceof V) vertices.add((V) obj);
                }
            }
        } catch (Exception ignored) {
            // ignore any exception during fallback
        }
    }
    return vertices;
}

