    // Parameter names may consist of letters, digits, underscore and dollar sign.
    // Anything else is treated as a separator indicating the end of a parameter name.
    return !Character.isLetterOrDigit(c) && c != '_' && c != '$';
}

private static boolean isParameterSeparator(final char c) {
    // A separator signals the end of a parameter name. Common separators are commas and
    // whitespace characters (spaces, tabs, newlines, etc.). This method conservatively
    // treats any whitespace as a separator and also treats a comma as a separator.
    try {
        return c == ',' || Character.isWhitespace(c);
    } catch (Exception e) {
        // In case of an unexpected runtime exception (unlikely since 'c' is a primitive),
        // return false to avoid breaking parsing logic.
        return false;
    }
}

private static boolean isParameterSeparator(final char c) {
    // Treat whitespace and common delimiters as separators for parameter names
    switch (c) {
        // Whitespace characters
        case ' ':
        case '\t':
        case '\n':
        case '\r':
            return true;

        // Common punctuation that separates parameters
        case ',':
        case ';':
        case '.':
            return true;

        // Parentheses and brackets
        case '(':
        case ')':
        case '[':
        case ']':
        case '{':
        case '}':
            return true;

        // Pipe and ampersand are sometimes used as separators
        case '|':
        case '&':
            return true;

        default:
            return false;
    }
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    final int strLen = str.length();
    final int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.regionMatches(false, strLen - suffixLen, suffix, 0, suffixLen);
    }
}

