public static String peek() {
    // Try to read the current thread's NDC stack without modifying it.
    // The stack is stored in a ThreadLocal variable called “contextStack”.
    // The contents can be held in a java.util.Stack or a java.util.Deque.
    try {
        Object ctx = contextStack.get();
        if (ctx == null) {
            return "";
        }
        if (ctx instanceof java.util.Stack) {
            java.util.Stack<String> stack = (java.util.Stack<String>) ctx;
            if (stack.isEmpty()) {
                return "";
            }
            return stack.peek();
        } else if (ctx instanceof java.util.Deque) {
            java.util.Deque<String> deque = (java.util.Deque<String>) ctx;
            if (deque.isEmpty()) {
                return "";
            }
            // The “top” of the NDC is the most recently pushed element,
            // which is the last element in the Deque.
            return deque.peekLast();
        } else {
            // Unexpected type – return an empty string.
            return "";
        }
    } catch (Exception e) {
        // In case of any unexpected runtime error, safely return empty string.
        return "";
    }
}

