public InputStream next() throws IOException {
    // Ensure that an iterator over the files has been initialized
    if (fileIterator == null) {
        throw new IllegalStateException("File iterator not initialized");
    }

    // Iterate until a valid file is found or the iterator is exhausted
    while (fileIterator.hasNext()) {
        java.io.File file = fileIterator.next();
        if (file == null) {
            // Skip null placeholders
            continue;
        }
        try {
            // Attempt to open an InputStream for the file
            return new java.io.FileInputStream(file);
        } catch (java.io.FileNotFoundException e) {
            // Skip files that are missing or inaccessible
            continue;
        }
    }

    // No more files available
    return null;
}

public InputStream next() throws IOException {
    try {
        if (fileIterator == null) {
            return null;
        }
        if (fileIterator.hasNext()) {
            java.io.File file = fileIterator.next();
            return new java.io.FileInputStream(file);
        }
        return null;
    } catch (java.io.FileNotFoundException e) {
        throw new java.io.IOException("Unable to open file", e);
    } catch (Exception e) {
