}

public InputStream next() throws IOException {
    // Return the next File as an InputStream, or null if no more files are available.
    // Assumes the class contains a List<File> named 'files' and an int 'currentIndex'.

    // If there are no files or we've exhausted the list, return null.
    if (files == null || currentIndex >= files.size()) {
        return null;
    }

    while (currentIndex < files.size()) {
        File file = files.get(currentIndex++);
        if (file == null || !file.isFile() || !file.canRead()) {
            // Skip invalid or unreadable files and continue.
            continue;
        }
        try {
            // Return a new FileInputStream for the file.
            return new FileInputStream(file);
        } catch (IOException e) {
            // If the file cannot be opened, log the issue (commented out) and continue.
            // Log.e("FileIterator", "Failed to open file: " + file.getAbsolutePath(), e);
            continue;
        }
    }
    // All remaining files were invalid/unreadable.
    return null;
}

public InputStream next() throws IOException {
    // Ensure the file list and current position are valid
    if (files == null || pos >= files.size()) {
        return null;
    }

    File nextFile = files.get(pos++);
    if (nextFile == null) {
        return null;
    }

    try {
        return new FileInputStream(nextFile);
    } catch (FileNotFoundException e) {
        // Re‑throw as generic IOException with context
