    // If no iterator or no more files, return null
    if (iterator == null || !iterator.hasNext()) {
        return null;
    }

    // Retrieve the next file
    File file = iterator.next();
    if (file == null) {
        return null;
    }

    // Return a FileInputStream for the retrieved file
    // Any IOException (e.g., FileNotFoundException) will propagate as declared
    return new FileInputStream(file);
}

