    double minY = box.getMinY();
    double maxX = box.getMaxX();
    double maxY = box.getMaxY();

    if (minX >= maxX) {
        throw new IllegalArgumentException("Box has non-positive width");
    }

    double midX = (minX + maxX) / 2.0;

    Box2D firstHalf = new Box2D(minX, minY, midX, maxY);
    Box2D secondHalf = new Box2D(midX, minY, maxX, maxY);

    return new Pair<>(firstHalf, secondHalf);
