        int currentCapacity = (buffer != null) ? buffer.length : 0;

        // Compute a new capacity that guarantees room for the requested additional bytes.
        // We use a doubling strategy to keep amortised growth linear.
        int newCapacity = Math.max(currentCapacity * 2, currentCapacity + size);

