            newCapacity = Integer.MAX_VALUE;
        }

        byte[] newBuffer = new byte[newCapacity];

        // Copy existing data to the new buffer if it already exists
        if (buffer != null) {
            System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        }

        // Replace the old buffer with the enlarged one
        buffer = newBuffer;
    } catch (OutOfMemoryError e) {
        // Convert the low‑level error into a runtime exception that can be caught by callers
        throw new RuntimeException("Unable to enlarge byte vector due to insufficient memory", e);
    }
}

