public int compare(Double o1, Double o2) {
    // Handle null values safely
    if (o1 == null && o2 == null) {
        return 0; // both null, considered equal
    }
    if (o1 == null) {
        return -1; // null is considered less than non-null
    }
    if (o2 == null) {
        return 1; // any non-null is greater than null
    }

    try {
        // Unbox to primitive double
        double d1 = o1.doubleValue();
        double d2 = o2.doubleValue();

        // If both are NaN, treat them as equal
        if (Double.isNaN(d1) && Double.isNaN(d2)) {
            return 0;
        }
        // NaN is considered greater than any other value
        if (Double.isNaN(d1)) {
            return 1;
        }
        if (Double.isNaN(d2)) {
            return -1;
        }

        // Delegate to Double.compare for standard ordering
        return Double.compare(d1, d2);
    } catch (Exception e) {
        // In rare cases where handling fails, fallback to safe comparison
        // Treat any exception as indicating inequality
        return 1;
    }
}

