    } catch (IOException e) {
        throw new RuntimeException("Unable to write verification_type_info entries", e);
    }
}

private void putAbstractTypes(final int start, final int end) {
    // Safety checks – if the frame or destination list is null, nothing to do.
    if (currentFrame == null || stackMapTableEntries == null) {
        return;
    }

    // Iterate over the requested slice of the frame and write each
    // entry into the stack map table using the JVMS verification_type_info format.
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.get(i);
        if (type == null) {/* skip null entries – they represent no type */}
        VerificationTypeInfo vt = new VerificationTypeInfo();

        // The tag is the core of each verification_type_info entry.
        vt.setTag(type.getTag());

        // For object types we also need the constant pool index of the class.
        if (type.isObject()) {
            int cpIndex = getConstantPoolIndex(type.getClassName());
            vt.setClassInfoIndex(cpIndex);
        }

        // For uninitialized types we need the offset where the new instance was
        // created in the bytecode.
        if (type.isUninitialized()) {
            vt.setOffset(type.getOffset());
        }

        stackMapTableEntries.add(vt);
    }
}

