@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type must not be null");
    }

    // Ensure we're requested to convert to Character (wrapper) or char (primitive)
    if (type != Character.class && type != char.class) {
        throw new ClassCastException("ConversionTarget is not Character or char");
    }

    // For primitive char, null is not allowed
    if (value == null) {
        if (type == char.class) {
            throw new IllegalArgumentException("Cannot convert null to primitive char");
        }
        return null; // null is acceptable for Character wrapper
    }

    // Direct conversion if already a Character
    if (value instanceof Character) {
        return value;
    }

    // From Number: cast numeric value to char
    if (value instanceof Number) {
        int numericValue = ((Number) value).intValue();
        return (char) numericValue;
    }

    // From String or CharSequence of length 1
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return cs.charAt(0);
        }
        throw new IllegalArgumentException(
                "Cannot convert CharSequence with length != 1 to Character: " + value);
    }

    // Special case: single-element char array
    if (value instanceof char[]) {
        char[] arr = (char[]) value;
        if (arr.length == 1) {
            return arr[0];
        }
        throw new IllegalArgumentException(
                "Cannot convert char array with length != 1 to Character: " + java.util.Arrays.toString(arr));
    }

    // Fallback: try to use toString and get first character if single-char string
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    throw new IllegalArgumentException(
            "Cannot convert value to java.lang.Character: " + value);
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure a non-null target type
    if (type == null) {
        throw new IllegalArgumentException("Target type must not be null");
    }

    // Support Character target (including primitive char)
    if (type == Character.class || type == char.class || type == Character.TYPE) {
        // Null values are accepted and passed through as null
        if (value == null) {
            return null;
        }

        // If already a Character, return as is
        if (value instanceof Character) {
            return value;
        }

        // String input: must be exactly one character long
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            } else {
                throw new Exception("Cannot convert String to Character: length is not 1");
            }
        }

        // Number input: convert numeric value to a character if within valid Unicode range
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
                return (char) intVal;
            } else {
                throw new Exception("Number value out of Character range");
            }
        }

        // Boolean input: interpret true as '1', false as '0'
        if (value instanceof Boolean) {
            return (boolean) value ? '1' : '0';
        }

        // Fallback: try to use the object's string representation, must be a single character
        String str = value.toString();
        if (str.length() == 1) {
            return str.charAt(0);
        }

        // If all attempts fail, throw an exception
        throw new Exception("Cannot convert value of type " + value.getClass().getName()
                + " to Character");
    }

    // If the requested type is not Character, throw an exception
    throw new Exception("Unsupported target type: " + type.getName());
}

