public static int nextPrime(int desiredCapacity){
    // Validate input
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }

    // Smallest prime to consider
    int candidate = Math.max(2, desiredCapacity);

    // Ensure candidate is odd (except when it's 2)
    if (candidate > 2 && candidate % 2 == 0) {
        candidate++;
    }

    // Upper bound for the search: 11% above desiredCapacity if >= 1000
    final int maxCandidate;
    if (desiredCapacity >= 1000) {
        // Compute 11% over capacity, add 1 to avoid rounding down to same number
        double upper = desiredCapacity * 1.11d + 1.0d;
        if (upper > Integer.MAX_VALUE - 2) {
            maxCandidate = Integer.MAX_VALUE - 2; // keep it odd
        } else {
            maxCandidate = (int) upper;
            if (maxCandidate % 2 == 0) {
                maxCandidate--; // keep odd
            }
        }
    } else {
        maxCandidate = Integer.MAX_VALUE - 2; // effectively no upper bound
    }

    while (candidate <= maxCandidate) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Skip even numbers
        candidate += 2;
        // Avoid overflow
        if (candidate < 0) {
            break;
        }
    }

    // As a last resort, try to continue searching beyond the 11% bound
    // (rare case – e.g., desiredCapacity close to Integer.MAX_VALUE)
    while (candidate > 0) { // stops if overflow
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
    }

    // If no prime could be found (should never happen in practice),
    // fall back to the maximum candidate reached
    if (maxCandidate >= 2) {
        return maxCandidate;
    }
    return 2;

}

