private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }
    // Integer.numberOfLeadingZeros returns the number of leading zero bits in the 32‑bit binary representation.
    // Subtracting this from 32 yields floor(log2(n)) + 1, which is the number of bits needed to represent n.
    return 32 - Integer.numberOfLeadingZeros(n);
}

private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be positive, got: " + n);
    }
    // The number of bits needed to represent n in binary is equal to floor(log2(n)) + 1.
    // Integer.numberOfLeadingZeros returns the count of leading zero bits in the 32‑bit representation.
    // Thus, 32 - numberOfLeadingZeros gives the bit length.
    return 32 - Integer.numberOfLeadingZeros(n);
}

private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    try {
        // Integer.numberOfLeadingZeros returns the number of leading zero bits in the two's complement binary representation of the specified int value.
        // For n > 0, the highest power of two <= n is at bit position (31 - numberOfLeadingZeros(n)).
        int highestBitIndex = 31 - Integer.numberOfLeadingZeros(n);
        return highestBitIndex + 1;
    } catch (Exception e) {
        // Wrap any unexpected exception and propagate
        throw new RuntimeException("Error computing binary log for n=" + n, e);
    }
}

private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    int log = 0;
    int temp = n;
    while (temp > 1) {
        temp >>= 1;
        log++;
    }
    return log + 1;
}

private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    return 32 - Integer.numberOfLeadingZeros(n);
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger = set1.size() > set2.size() ? set1 : set2;
    Set<V> result = new HashSet<>(smaller.size());
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

