protected int removeUnusedNodes(){
    try{
        if (root == null) {
            return 0;
        }
        if (!root.isActive()){
            int removed = removeAll(root);
            root = null; // clear reference to the root
            return removed;
        }
        return removeUnusedNodesFrom(root);
    }catch(Exception e){
        // In case of unexpected errors, return 0 to indicate no nodes removed
        return 0;
    }
}

private int removeUnusedNodesFrom(Category node){
    int removedCount = 0;
    java.util.List<Category> children = node.getChildren();
    if (children != null) {
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()){
            Category child = it.next();
            if (!child.isActive()){
                removedCount += removeAll(child);
                it.remove(); // remove inactive node and its subtree
            } else {
                removedCount += removeUnusedNodesFrom(child);
            }
        }
    }
    return removedCount;
}

private int removeAll(Category node){
    int count = 1; // count the node itself
    java.util.List<Category> children = node.getChildren();
    if (children != null) {
        for (Category child : children) {
            count += removeAll(child);
        }
    }
    return count;
}

protected int removeUnusedNodes() {
    // Check for non-existent tree
    if (root == null) {
        return 0;
    }
    // Recursively clean up the tree starting from the root
    return removeUnusedNodesRecursive(root);
}

// Helper to recursively clean a subtree and count removed nodes
private int removeUnusedNodesRecursive(Category node) {
    if (node == null) {
        return 0;
    }
    int removed = 0;
    List<Category> children = node.getChildren();
    if (children == null) {
        return 0;
    }
    Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (child == null) {
            continue;
        }
        if (!child.isActive()) {
            // Remove entire subtree rooted at this inactive node
            removed += countNodes(child);
            it.remove();
        } else {
            // Recursively process active child
            removed += removeUnusedNodesRecursive(child);
        }
    }
    return removed;
}

// Counts all nodes in a subtree rooted at the given node (inclusive)
private int countNodes(Category node) {
    if (node == null) {
        return 0;
    }
    int count = 1; // count this node
    List<Category> children = node.getChildren();
    if (children != null) {
        for (Category child : children) {
            count += countNodes(child);
        }
    }
    return count;
}

protected int removeUnusedNodes() {
    // Attempt to remove inactive nodes from the category tree.
    // Return the number of root nodes that were removed.
    try {
        if (root == null) {
            return 0;
        }

        // If the root itself is inactive, the entire tree is removed.
        if (!root.isActive()) {
            root = null;
            return 1;
        }

        int removedCount = 0;
        java.util.ArrayDeque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            Category current = stack.pop();
            java.util.List<Category> children = current.getChildren();
            java.util.Iterator<Category> itr = children.iterator();

            while (itr.hasNext()) {
                Category child = itr.next();
                if (!child.isActive()) {
                    // Remove inactive child from the current node's children list.
                    itr.remove();
                    removedCount++;
                    // No need to traverse this child's descendants, they are implicitly removed.
                } else {
                    // Active child: add to stack for further processing.
                    stack.push(child);
                }
            }
        }

        return removedCount;
    } catch (Exception e) {
        // In case of any unexpected errors, return 0 removed.
        return 0;
    }
}

