            }
            // Advance according to dir (1 for next/clockwise, -1 for prev/counter-clockwise)
            if (dir > 0) {
                current = current.getNext();
            } else {
                current = current.getPrev();
            }
            if (current == null) {
                // Safety check: if traversal ends unexpectedly, return stop circulator
                return new OuterFaceCirculator(stop);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error while selecting node on outer face", e);
