        }
    }
    // Return the next byte
    return buffer[bufferPos++];
}

public byte readByte() throws IOException {
    // If the buffer has no more data, attempt to refill it from the underlying input stream.
    if (pos >= limit) {
        // Read into the buffer; this will block until data is available or end of stream is reached.
        int bytesRead = in.read(buf);
        if (bytesRead <= 0) { // No more data available.
            throw new IOException("End of stream reached while attempting to read a byte");
        }
        // Reset pointers for the newly filled buffer.
        pos = 0;
        limit = bytesRead;
    }
    // Return the next byte from the buffer.
    return buf[pos++];
}

