    // Basic validation
    if (graph == null || tour == null) {
        return null;
    }
    // If the tour is empty, return an empty path
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null,
                                new java.util.ArrayList<>(),
                                new java.util.ArrayList<>(),
                                0.0);
    }
    // Use a mutable set to keep track of remaining edges
    java.util.Set<E> remaining = new java.util.HashSet<>(tour);
    // Pick an arbitrary first edge
    E startEdge = remaining.iterator().next();
    remaining.remove(startEdge);

    // Determine starting vertex and initial direction
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = graph.getEdgeTarget(startEdge);

    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    vertexList.add(startVertex);
    edgeList.add(startEdge);

    double totalWeight = graph.getEdgeWeight(startEdge);

    try {
        // Traverse edges until all are consumed
        while (!remaining.isEmpty()) {
            boolean found = false;
            for (E e : remaining) {
                V src = graph.getEdgeSource(e);
                V tgt = graph.getEdgeTarget(e);
                boolean isDirect = graph.getType().isDirected();

                // Check if the edge is connected to current vertex
                if ((isDirect && src.equals(currentVertex)) ||
                    (!isDirect && (src.equals(currentVertex) || tgt.equals(currentVertex)))) {
                    // Consume this edge
                    remaining.remove(e);
                    edgeList.add(e);
                    totalWeight += graph.getEdgeWeight(e);

                    // Determine next vertex
                    if (src.equals(currentVertex)) {
                        currentVertex = tgt;
                    } else {
                        currentVertex = src;
                    }
                    vertexList.add(currentVertex);
                    found = true;
                    break;
                }
            }
            if (!found) {
                // No connecting edge found -> invalid tour
                return null;
            }
        }
    } catch (Exception ex) {
        return null;
    }

    // Return the constructed tour as a GraphWalk
    return new GraphWalk<>(graph, startVertex, currentVertex, vertexList, edgeList, totalWeight);
}

