protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (tour == null) {
        throw new IllegalArgumentException("Tour must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    // Verify all edges belong to the graph
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not part of the specified graph");
        }
    }
    // Build ordered edge list
    List<E> orderedEdges = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    // Pick an arbitrary starting edge
    Iterator<E> edgeIter = tour.iterator();
    E startEdge = edgeIter.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = startVertex;
    vertexList.add(currentVertex);
    orderedEdges.add(startEdge);
    Set<E> remaining = new HashSet<>(tour);
    remaining.remove(startEdge);
    // Traverse remaining edges
    while (!remaining.isEmpty()) {
        boolean foundNext = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex)) {
                currentVertex = tgt;
                orderedEdges.add(e);
                vertexList.add(currentVertex);
                it.remove();
                foundNext = true;
                break;
            } else if (tgt.equals(currentVertex)) {
                currentVertex = src;
                orderedEdges.add(e);
                vertexList.add(currentVertex);
                it.remove();
                foundNext = true;
                break;
            }
        }
        if (!foundNext) {
            throw new RuntimeException("Cannot order edges into a coherent path; graph may be disconnected or edges invalid");
        }
    }
    V endVertex = currentVertex;
    double weight = 0.0;
    for (E e : orderedEdges) {
        weight += graph.getEdgeWeight(e);
    }
    // Construct and return a GraphPath instance
    return new GraphPath<V,E>() {
        @Override public Graph<V,E> getGraph() { return graph; }
        @Override public V getStartVertex() { return startVertex; }
        @Override public V getEndVertex() { return endVertex; }
        @Override public List<V> getVertexList() { return vertexList; }
        @Override public List<E> getEdgeList() { return orderedEdges; }
        @Override public double getWeight() { return weight; }
    };
}

