public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int dotIndex = path.lastIndexOf('.');
    if (dotIndex == -1) {
        return null;
    }
    int slashIndex = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    if (dotIndex <= slashIndex) {
        return null;
    }
    return path.substring(0, dotIndex);
}

public static String stripFilenameExtension(String path) {
    // Return null for null or empty input
    if (path == null || path.isEmpty()) {
        return null;
    }

    // Find the last file separator (handles both Unix '/' and Windows '\\')
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));

    // Find the last dot in the path
    int lastDot = path.lastIndexOf('.');

    // If there is no dot, the dot is in a directory, or the dot is the last character,
    // consider that there is no effective filename extension.
    if (lastDot <= lastSeparator || lastDot == path.length() - 1) {
        return null;
    }

    // Return the path up to (but not including) the last dot
    return path.substring(0, lastDot);
}

