private String parseToken(final char[] terminators) {
    // Ensure the terminators array is valid
    if (terminators == null) {
        throw new IllegalArgumentException("terminators array cannot be null");
    }

    // Build the token using a StringBuilder for efficiency
    StringBuilder token = new StringBuilder();

    try {
        // Assume that this class has a 'pos' index and a 'buffer' array
        // that hold the current parsing state.
        while (pos < buffer.length) {
            char c = buffer[pos];

            // Check if the current character is a terminator
            boolean isTerminator = false;
            for (char t : terminators) {
                if (c == t) {
                    isTerminator = true;
                    break;
                }
            }

            // Stop parsing if we hit a terminator character
            if (isTerminator) {
                break;
            }

            // Append the character to the token and advance the position
            token.append(c);
            pos++;
        }
    } catch (Exception e) {
        // In case of any unexpected failure, wrap and rethrow
        throw new RuntimeException("Failed to parse token", e);
    }

    // Return the accumulated token (may be empty if no characters were read)
    return token.toString();
}

private String parseToken(final char[] terminators){
    // Ensure terminators array is safe to use
    if (terminators == null) {
        throw new IllegalArgumentException("Terminator array cannot be null");
    }
    StringBuilder token = new StringBuilder();
    try {
        // Assume there are fields `buffer` (char array) and `index` (current position)
        while (index < buffer.length) {
            char current = buffer[index];
            // Check if current character is a terminator
            for (char term : terminators) {
                if (current == term) {
                    return token.toString(); // token ends when a terminator is found
                }
            }
            token.append(current);
            index++;
        }
    } catch (ArrayIndexOutOfBoundsException | NullPointerException e) {
        // Gracefully handle unexpected state
        return token.toString();
    }
    // Return any accumulated characters (handles EOF without terminator)
    return token.toString();
}

public static String trimLeadingCharacter(String str, char leadingCharacter) {
    // Return null if the input string is null to avoid NullPointerException
    if (str == null) {
        return null;
    }

    int length = str.length();
    int index = 0;

    // Find the first character that is not the leadingCharacter
    while (index < length && str.charAt(index) == leadingCharacter) {
        index++;
    }

    // Substring from the first non-leading character (or empty if all were trimmed)
    return str.substring(index);
}

