private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    List<Integer> suffixSums = new ArrayList<>(bounds.size());
    long totalSum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null at index " + i);
        }
        totalSum += val;
        suffixSums.add(0, (int) totalSum); // cast to int as list holds Integer
    }
    return new Pair<>(suffixSums, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    try {
        if (bounds == null || bounds.isEmpty()) {
            return new Pair<>(new ArrayList<>(), 0L);
        }
        int n = bounds.size();
        long totalSum = 0L;
        for (Integer b : bounds) {
            if (b != null) {
                totalSum += b;
            }
        }
        int[] suffixArr = new int[n];
        long current = 0L;
        for (int i = n - 1; i >= 0; i--) {
            Integer b = bounds.get(i);
            if (b != null) {
                current += b;
            }
            suffixArr[i] = (int) current;
        }
        List<Integer> suffixList = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            suffixList.add(suffixArr[i]);
        }
        return new Pair<>(suffixList, totalSum);
    } catch (Exception e) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Prepare the suffix sum list
    int n = (bounds == null) ? 0 : bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(0); // placeholder
    }

    long total = 0L;
    try {
        for (int i = n - 1; i >= 0; i--) {
            Integer value = bounds.get(i);
            long val = (value != null) ? value.longValue() : 0L;
            total += val;
            // Cast back to Integer; overflow will wrap around like normal int arithmetic
            suffix.set(i, (int) total);
        }
    } catch (Exception e) {
        // In case of any runtime unexpected issue, treat as empty result
        return new Pair<>(new ArrayList<>(), 0L);
    }

    return new Pair<>(suffix, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long total = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        Integer curObj = bounds.get(i);
        if (curObj == null) {
            throw new IllegalArgumentException("bounds contains null element at index " + i);
        }
        int cur = curObj;
        total += cur;
        suffix.add(0, (int) total); // insert at front to preserve suffix order
    }
    return new Pair<>(suffix, total);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    try {
        if (bounds == null) {
            throw new IllegalArgumentException("bounds list cannot be null");
        }
        int n = bounds.size();
        List<Integer> suffix = new ArrayList<>(n);
        long running = 0L;
        for (int i = n - 1; i >= 0; i--) {
            Integer val = bounds.get(i);
            if (val == null) {
                throw new IllegalArgumentException("bounds list contains null element at index " + i);
            }
            running += val;
            suffix.add((int) running); // truncating to int as per method signature
        }
        Collections.reverse(suffix); // restore original order
        return new Pair<>(suffix, running);
    } catch (Exception ex) {
        // In case of any exception, return empty result with zero sum
        return new Pair<>(Collections.emptyList(), 0L);
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int length = arr.length;
    if (from < 0 || to < 0 || from >= length || to >= length) {
        throw new IllegalArgumentException("Indices out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to to index");
    }
    try {
        while (from < to) {
            V temp = arr[from];
            arr[from] = arr[to];
            arr[to] = temp;
            from++;
            to--;
        }
    } catch (Exception e) {
        // Wrap any unexpected exception in a RuntimeException for caller visibility
        throw new RuntimeException("Failed to reverse array segment", e);
    }
}

public static final <V> void reverse(V[] arr,int from,int to){
    if(arr==null){
        throw new IllegalArgumentException("Array cannot be null");
    }
    int len = arr.length;
    if(from < 0 || to < 0 || from >= len || to >= len || from > to){
        throw new IllegalArgumentException("Invalid indices: from=" + from + ", to=" + to + ", length=" + len);
    }
    int i = from, j = to;
    while(i < j){
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        throw new IllegalArgumentException("Indices out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("'from' index cannot be greater than 'to' index");
    }
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        ++i;
        --j;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    int n = arr.length;
    if (from < 0 || to < 0 || from >= n || to >= n) {
        throw new IndexOutOfBoundsException(
            "Index out of bounds: from=" + from + ", to=" + to + ", array length=" + n);
    }
    if (from > to) {
        // Nothing to reverse when the range is invalid (start greater than end)
        return;
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Validate input
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null.");
    }
    // No-op if both lists are the same
    if (this == list) {
        return;
    }

    // Atomically move each node from the source list to this list.
    // The naive approach (removing each node and then adding it)
    // will work even without knowing the exact internal fields of the list.
    // It relies on the public API: removeListNode(node) and addListNode(node).
    // We use a while-loop that continues until the source list is empty.
    try {
        // Initial reference to the first node of the source list.
        ListNodeImpl<E> node = list.getFirstNode(); // getFirstNode() is assumed to exist.
        // If that method does not exist, this line can be replaced with list.getHead() or
        // list.getListHead(), depending on the actual implementation.
        while (node != null) {
            // Remove the node from the source list
            list.removeListNode(node);

            // Add the node to this list
            this.addListNode(node);

            // Advance to the next node in the source list
            node = list.getFirstNode(); // get the new first node after removal
        }
    } catch (Exception e) {
        // If any runtime exception occurs during the process, wrap it in an
        // IllegalStateException to avoid leaking implementation details.
        throw new IllegalStateException("Failed to move nodes from source list.", e);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Validate inputs
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        return; // nothing to move
    }
    if (list.size == 0) {
        return; // nothing to move
    }

    // Grab first and last real nodes from the source list
    ListNodeImpl<E> srcFirst = list.firstNode.next; // first actual node
    ListNodeImpl<E> srcLast  = list.lastNode.prev;  // last actual node

    // Detach entire chain from source list
    list.firstNode.next = list.lastNode;
    list.lastNode.prev  = list.firstNode;
    int movedSize = list.size;
    list.size = 0;

    // Find insertion point in this list (before the last sentinel)
    ListNodeImpl<E> destPrev = this.lastNode.prev;

    // Wire the source chain into this list
    destPrev.next = srcFirst;
    srcFirst.prev = destPrev;
    srcLast.next  = this.lastNode;
    this.lastNode.prev = srcLast;

    // Update this list's size
    this.size += movedSize;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Reject null to avoid a NullPointerException and provide a clear error message.
    if (list == null) {
        throw new IllegalArgumentException("The source list cannot be null");
    }

    // Moving to self is a no-op – it keeps the list unchanged and avoids circular reference.
    if (list == this) {
        return;
    }

    // If the source list is empty we also do nothing.
    if (list.isEmpty()) {
        return;
    }

    // We will link the two chains together in a single operation so that the operation
    // appears atomic from a caller’s perspective.  This assumes that the DoublyLinkedList
    // exposes its head and tail pointers as package‑private fields or that this method
    // is defined inside the same package.  The ListNodeImpl generic type is the node
    // type used by the list implementation.
    try {
        // Grab the boundary nodes of the source list.  These are the first and last
        // nodes in the chain we want to move.
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> srcFirst = (ListNodeImpl<E>) list.getHead();
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> srcLast  = (ListNodeImpl<E>) list.getTail();

        // If the destination list is empty, just adopt the source list’s chain.
        if (this.isEmpty()) {
            this.head = srcFirst;
            this.tail = srcLast;
        } else {
            // Otherwise link the existing tail of this list to the head of the
            // source list, then update the tail reference to the source list’s tail.
            this.tail.setNext(srcFirst);   // tail.next = srcFirst
            srcFirst.setPrev(this.tail);   // srcFirst.prev = tail
            this.tail = srcLast;           // new tail is the old source tail
        }

        // Total size of the destination list increases by the number of moved nodes.
        this.size += list.size();

        // Finally, clear the source list to reflect that it no longer contains any
        // nodes.  All references between the moved nodes are kept intact, so the
        // garbage collector will not prematurely collect them.
        list.head = null;
        list.tail = null;
        list.size = 0;
    } catch (Throwable t) {
        // In case anything goes unexpectedly wrong – for example, the fields are
        // not accessible – we throw an IllegalStateException which signals a
        // contract violation in the list implementation rather than silently
        // swallowing the problem.
        throw new IllegalStateException("Failed to move all nodes: " + t.getMessage(), t);
    }
}

/**
 * Atomically moves all {@link ListNode ListNodes} from {@code list} to this list as if each node was
 * removed with {@link #removeListNode(ListNodeImpl)} from {@code list} and subsequently added to
 * this list by {@link #addListNode(ListNodeImpl)}.
 *
 * @param list the source list from which to move all nodes
 * @throws IllegalArgumentException if {@code list} is {@code null}
 * @throws RuntimeException         if any removal or addition operation fails
 */
private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        return; // nothing to do
    }

    /* Acquire locks in a fixed order to avoid potential dead‑lock.
     * We lock the object with the smaller identity hash code first. */
    Object firstLock, secondLock;
    if (System.identityHashCode(this) < System.identityHashCode(list)) {
        firstLock = this;
        secondLock = list;
    } else {
        firstLock = list;
        secondLock = this;
    }

    synchronized (firstLock) {
        synchronized (secondLock) {
            // Traverse the source list and transfer each node.
            ListNodeImpl<E> current = (ListNodeImpl<E>) list.head;
            while (current != null) {
                // Keep a reference to the next node before we dismantle links.
                ListNodeImpl<E> next = (ListNodeImpl<E>) current.next;
                try {
                    // Remove from the source and add to the destination.
                    list.removeListNode(current);
                    this.addListNode(current);
                } catch (RuntimeException e) {
                    // If an exception occurs, we can't guarantee atomicity.
                    // Propagate the error to the caller.
                    throw new RuntimeException("Failed to move nodes between lists", e);
                }
                current = next;
            }
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        // Moving nodes from a list to itself is a no‑op
        return;
    }
    // If the source list is empty, nothing needs to be moved
    if (list.size == 0) {
        return;
    }

    // Link the two lists
    if (this.size == 0) {
        // Target list is empty – simply adopt the source list
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Both lists are non‑empty – splice the source list onto the tail
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }

    // Update sizes
    this.size += list.size;
    list.size = 0;

    // Detach the source list
    list.head = null;
    list.tail = null;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If either argument is null, only return true when both are null.
    if (str == null || prefix == null) {
        return str == null && prefix == null;
    }

    // If prefix is longer than the string, it cannot match.
    if (prefix.length() > str.length()) {
        return false;
    }

    // Perform comparison, respecting the ignoreCase flag.
    if (ignoreCase) {
        // regionMatches handles case-insensitive comparison without allocating new strings.
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && prefix == null) {
        return true;
    }
    // If only one is null, no match
    if (str == null || prefix == null) {
        return false;
    }
    // Prefix longer than string cannot match
    if (prefix.length() > str.length()) {
        return false;
    }
    // Perform case-sensitive or case-insensitive comparison
    if (ignoreCase) {
        // regionMatches handles case-insensitive comparison and is null-safe for this branch
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null && prefix == null) {
        return true;
    }
    if (str == null || prefix == null) {
        return false;
    }
    if (ignoreCase) {
        // regionMatches with ignore case set to true
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    }
    return str.startsWith(prefix);
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase){
    if (str == null && prefix == null) {
        return true;
    }
    if (str == null || prefix == null) {
        return false;
    }
    if (prefix.length() > str.length()) {
        return false;
    }
    return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null) {
        return prefix == null; // true only when both are null
    }
    if (prefix == null) {
        return false; // str non‑null, prefix null
    }
    int len = prefix.length();
    if (len > str.length()) {
        return false;
    }
    return ignoreCase
            ? str.regionMatches(true, 0, prefix, 0, len)
            : str.startsWith(prefix);
}

