    if (toSplit == null || delimiter == null) {
        throw new IllegalArgumentException("Input string and delimiter must not be null.");
    }
    if (delimiter.isEmpty()) {
        throw new IllegalArgumentException("Delimiter must not be empty.");
    }

    try {
        int idx = toSplit.indexOf(delimiter);
        if (idx < 0) {
            return null; // delimiter not found
        }
        String before = toSplit.substring(0, idx);
        String after = toSplit.substring(idx + delimiter.length());
        return new String[]{before, after};
    } catch (Exception e) {
        // In case of unexpected runtime exceptions, wrap and rethrow
        throw new RuntimeException("Failed to split string: " + e.getMessage(), e);
    }
}

