private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("vertices must not be null");
    }

    // A set with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();

    for (int i = 0; i < n; i++) {
        V vi = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = vertexList.get(j);
            // In an undirected graph we need an edge in either direction.
            // In a directed graph we consider either orientation as sufficient
            // for the purpose of detecting a clique in the induced subgraph.
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertex set must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    // Ensure all vertices belong to the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }
    java.util.List<V> list = new java.util.ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V v1 = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V v2 = list.get(j);
            boolean connected = graph.containsEdge(v1, v2) || graph.containsEdge(v2, v1);
            if (!connected) {
                return false;
            }
        }
    }
    return true;
}

