private <K extends Comparable<? super K>> List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    int size = keys.size();
    List<Integer> lowerBoundIndices = new ArrayList<>(size);
    for (int i = 0; i < size; i++) {
        K current = keys.get(i);
        int maxLowerIdx = -1;
        for (int j = 0; j < size; j++) {
            if (i == j) continue;
            K other = keys.get(j);
            if (other.compareTo(current) < 0) { // other < current
                if (maxLowerIdx == -1 || other.compareTo(keys.get(maxLowerIdx)) > 0) {
                    maxLowerIdx = j;
                }
            }
        }
        lowerBoundIndices.add(maxLowerIdx);
    }
    return lowerBoundIndices;
}

private List<Integer> computeLowerBounds(List<K> keys){
    java.util.List<Integer> results = new java.util.ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return results;
    }
    java.util.List<K> sorted = new java.util.ArrayList<>(keys);
    try {
        sorted.sort(null);
    } catch (ClassCastException e) {
        throw new IllegalArgumentException("Keys must be mutually comparable", e);
    }
    for (K key : keys){
        if (key == null){
            results.add(-1);
            continue;
        }
        int idx;
        try {
            idx = java.util.Collections.binarySearch(sorted, key);
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("Key is not comparable", e);
        }
        if (idx < 0){
            idx = -idx - 2; // insertion point - 1 gives last element <= key
        } else {
            // move to the last occurrence of key if duplicates exist
            while (idx + 1 < sorted.size() && sorted.get(idx + 1).compareTo(key) <= 0){
                idx++;
            }
        }
        results.add(idx >= 0 ? idx : -1);
    }
    return results;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            lowerBounds.add(null);
            continue;
        }
        Integer maxLower = null;
        for (K candidate : keys) {
            if (candidate == null || candidate == key) {
                continue;
            }
            try {
                boolean lowerThanKey = false;
                Integer candidateValue = null;
                Integer keyValue = null;

                // If key is Comparable, use its compareTo
                if (key instanceof Comparable) {
                    @SuppressWarnings("unchecked")
                    Comparable<K> compKey = (Comparable<K>) key;
                    int cmp = compKey.compareTo(candidate);
                    if (cmp > 0) {
                        lowerThanKey = true;
                    }
                }

                // If not Comparable or comparison not conclusive, attempt numeric comparison via Number or parsing
                if (!lowerThanKey) {
                    if (key instanceof Number) {
                        keyValue = ((Number) key).intValue();
                        if (candidate instanceof Number) {
                            candidateValue = ((Number) candidate).intValue();
                            if (candidateValue < keyValue) {
                                lowerThanKey = true;
                            }
                        } else {
                            try {
                                candidateValue = Integer.parseInt(candidate.toString());
                                if (candidateValue < keyValue) {
                                    lowerThanKey = true;
                                }
                            } catch (NumberFormatException e) {
                                // ignore, cannot compare numerically
                            }
                        }
                    } else {
                        try {
                            keyValue = Integer.parseInt(key.toString());
                            if (candidate instanceof Number) {
                                candidateValue = ((Number) candidate).intValue();
                                if (candidateValue < keyValue) {
                                    lowerThanKey = true;
                                }
                            } else {
                                candidateValue = Integer.parseInt(candidate.toString());
                                if (candidateValue < keyValue) {
                                    lowerThanKey = true;
                                }
                            }
                        } catch (NumberFormatException e) {
                            // cannot compare
                        }
                    }
                }

                if (lowerThanKey) {
                    if (candidateValue == null && candidate instanceof Number) {
                        candidateValue = ((Number) candidate).intValue();
                    } else if (candidateValue == null) {
                        try {
                            candidateValue = Integer.parseInt(candidate.toString());
                        } catch (NumberFormatException e) {
                            // ignore
                        }
                    }
                    if (candidateValue != null && (maxLower == null || candidateValue > maxLower)) {
                        maxLower = candidateValue;
                    }
                }
            } catch (Exception e) {
                // ignore individual comparison failures
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    // Prepare the result list
    List<Integer> lowerBounds = new ArrayList<>(keys != null ? keys.size() : 0);
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }

    // Create a list of index/key pairs
    List<Pair<K, Integer>> indexedKeys = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        indexedKeys.add(new Pair<>(keys.get(i), i));
    }

    // Sort the pairs by their key values
    indexedKeys.sort((p1, p2) -> {
        K k1 = p1.getFirst();
        K k2 = p2.getFirst();
        if (k1 == null && k2 == null) {
            return 0;
        }
        if (k1 == null) {
            return -1;
        }
        if (k2 == null) {
            return 1;
        }
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> comp1 = (Comparable<Object>) k1;
            return comp1.compareTo(k2);
        } catch (Exception e) {
            // In case the key is not Comparable, treat it as equal
            return 0;
        }
    });

    // Compute lower bounds (count of elements less than or equal to each key)
    int[] bounds = new int[keys.size()];
    for (int i = 0; i < indexedKeys.size(); i++) {
        bounds[indexedKeys.get(i).getSecond()] = i;
    }

    // Populate result list
    for (int i = 0; i < bounds.length; i++) {
        lowerBounds.add(bounds[i]);
    }

    return lowerBounds;
}

