    Deque<Object> stack = this.outputStack; // Assumes a field named outputStack exists in the enclosing class
    boolean readingArgs = false;
    try {
        if (descriptor.charAt(0) == '(') {
            pos = 1;
            readingArgs = true;
        }
        while (pos < descriptor.length()) {
            if (readingArgs && descriptor.charAt(pos) == ')') {
                break; // end of argument list; return type is ignored
            }
            // Skip array brackets
            while (descriptor.charAt(pos) == '[') {
                pos++;
            }
            char c = descriptor.charAt(pos);
            int slots;
            if (c == 'L') { // object or interface type
                int semicolon = descriptor.indexOf(';', pos);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                }
                slots = 1;
                pos = semicolon + 1;
            } else if (c == 'J' || c == 'D') { // long or double occupy two slots
                slots = 2;
                pos++;
            } else { // other primitive types occupy one slot
                slots = 1;
                pos++;
            }
            for (int i = 0; i < slots; i++) {
                if (stack.isEmpty()) {
                    throw new IllegalStateException("Stack underflow while popping descriptor: " + descriptor);
                }
                stack.pop();
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Malformed descriptor: " + descriptor, e);
    }
}

private void pop(final String descriptor){
