        if (descriptor.charAt(0) == '('){
            pos = 1;
            while (pos < descriptor.length() && descriptor.charAt(pos) != ')'){
                pos = popType(descriptor, pos);
            }
        }else{
            popType(descriptor, 0);
        }
    }catch (Exception e){
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

private int popType(String desc, int index){
    char c = desc.charAt(index);
    switch (c){
        case 'B': case 'C': case 'F':
        case 'I': case 'S': case 'Z':
        case 'V':
            popStackSlot();
            return index+1;
        case 'J': case 'D':
            popStackSlot();
            popStackSlot();
            return index+1;
        case '[':
            return popArray(desc, index);
        case 'L':
            int semi = desc.indexOf(';', index);
            if (semi == -1){
                throw new IllegalArgumentException("unterminated reference type");
            }
            popStackSlot();
            return semi+1;
        default:
            throw new IllegalArgumentException("unknown descriptor char: "+c);
    }
}

private int popArray(String desc, int index){
    while (desc.charAt(index) == '['){
        index++;
        if (index >= desc.length()){
            throw new IllegalArgumentException("invalid array descriptor");
        }
    }
    return popType(desc, index);
}

private void popStackSlot(){
    // Assumes there is a field named 'stack' or similar that holds the output frame stack.
    // The actual stack type is not specified; change the following line to match the real stack implementation.
    stack.pop();  // remove the top element
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }
    int i = 0;
    final int len = descriptor.length();
    if (descriptor.charAt(i) == '('){
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')'){
            int typeLen = typeLength(descriptor, i);
            char typeStart = descriptor.charAt(i);
            if (typeStart != 'V'){
                if (stack.isEmpty()){
                    throw new IllegalStateException("Stack underflow while popping method arguments");
                }
                stack.pop();
            }
            i += typeLen;
        }
        if (i >= len){
            throw new IllegalArgumentException("Malformed descriptor: missing ')'");
        }
        i++; // skip ')'
        if (i < len){
            // consume return type (but do not pop anything for it)
            int _ = typeLength(descriptor, i);
            i += _;
        }
    }else{
        int typeLen = typeLength(descriptor, i);
        char typeStart = descriptor.charAt(i);
        if (typeStart != 'V'){
            if (stack.isEmpty()){
                throw new IllegalStateException("Stack underflow while popping descriptor");
            }
            stack.pop();
        }
        i += typeLen;
        if (i != len){
            throw new IllegalArgumentException("Invalid descriptor format: unexpected trailing characters");
        }
    }
}

private int typeLength(String desc, int pos){
    char ch = desc.charAt(pos);
    if (ch == '['){
        int i = pos;
        while (desc.charAt(i) == '[') i++;
        if (desc.charAt(i) == 'L'){
            i++; // skip 'L'
            while (desc.charAt(i) != ';') i++;
            i++; // skip ';'
        }else{
            i++; // primitive type
        }
        return i - pos;
    }else if (ch == 'L'){
        int i = pos + 1;
        while (desc.charAt(i) != ';') i++;
        i++; // skip ';'
        return i - pos;
    }else{
        return 1; // primitive or void
    }
}

private void pop(final String descriptor){
    if (descriptor == null){
        throw new IllegalArgumentException("descriptor == null");
    }
    int count = 0;
    int i = 0;
    // method descriptor: pop all argument types
    if (descriptor.charAt(0) == '('){
        i = 1;
        while (descriptor.charAt(i) != ')'){
            char c = descriptor.charAt(i);
            int argSize;
            if (c == 'J' || c == 'D'){
                argSize = 2;
                i++;
            } else if (c == '['){
                // skip entire array type
                do{
                    i++;
                } while (descriptor.charAt(i) == '[');
                while (descriptor.charAt(i) != ';'){
                    i++;
                }
                i++; // skip ';'
                argSize = 1;
            } else if (c == 'L'){
                i++; // skip 'L'
                while (descriptor.charAt(i) != ';'){
                    i++;
                }
                i++; // skip ';'
                argSize = 1;
            } else {
                // primitive
                argSize = 1;
                i++;
            }
            count += argSize;
        }
        // skip ')'
        i++;
    } else {
        // single type descriptor
        char c = descriptor.charAt(0);
        count = (c == 'J' || c == 'D') ? 2 : 1;
    }

    if (count > stack.size()){
        throw new IllegalStateException("insufficient stack entries: needed " + count + ", available " + stack.size());
    }
    for (int k = 0; k < count; k++){
        stack.pop();
    }
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Assume the class has a field named outputStack representing the output frame stack.
    Deque<AbstractType> stack = outputStack;
    if (stack == null) {
        throw new IllegalStateException("Output stack not initialized");
    }

    String desc = descriptor.trim();
    if (desc.isEmpty()) {
        return;
    }

    int typesToPop = 0;
    try {
        if (desc.charAt(0) == '(') { // Method descriptor
            int pos = 1;
            while (pos < desc.length() && desc.charAt(pos) != ')') {
                pos = consumeType(desc, pos);
                typesToPop++;
            }
            if (pos >= desc.length() || desc.charAt(pos) != ')') {
                throw new IllegalArgumentException("Malformed method descriptor: missing closing parenthesis");
            }
            // The return type after ')' is ignored for popping.
        } else { // Field descriptor
            consumeType(desc, 0);
            typesToPop = 1;
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Malformed descriptor: " + descriptor, e);
    }

    for (int i = 0; i < typesToPop; i++) {
        if (stack.isEmpty()) {
            throw new IllegalStateException("Output frame stack underflow while popping descriptor: " + descriptor);
        }
        stack.pop();
    }
}

/**
 * Consumes a single type starting at the given index and returns the index after the type.
 *
 * @param s   the descriptor string
 * @param pos the current index within the string
 * @return the index after the type
 */
private int consumeType(String s, int pos) {
    if (pos >= s.length()) {
        throw new IndexOutOfBoundsException("Unexpected end of descriptor");
    }
    char c = s.charAt(pos);
    if (c == '[') { // array type
        // eat all '['
        while (pos < s.length() && s.charAt(pos) == '[') {
            pos++;
        }
        // eat the element type
        if (pos < s.length()) {
            if (s.charAt(pos) == 'L') {
                pos++; // skip 'L'
                while (pos < s.length() && s.charAt(pos) != ';') {
                    pos++;
                }
                if (pos < s.length() && s.charAt(pos) == ';') {
                    pos++; // skip ';'
                } else {
                    throw new IndexOutOfBoundsException("Unterminated class name in descriptor");
                }
            } else {
                // primitive component
                pos++; // single byte
            }
        } else {
            throw new IndexOutOfBoundsException("Unexpected end of descriptor after array brackets");
        }
    } else if (c == 'L') { // object type
        pos++; // skip 'L'
        while (pos < s.length() && s.charAt(pos) != ';') {
            pos++;
        }
        if (pos < s.length() && s.charAt(pos) == ';') {
            pos++; // skip ';'
        } else {
            throw new IndexOutOfBoundsException("Unterminated class name in descriptor");
        }
    } else { // primitive type
        pos++; // single byte
    }
    return pos;
}

