        return -1; // no dot found
    }

    // Position of the last file separator ('/' or '\')
    int lastSeparatorIdx = Math.max(
            filename.lastIndexOf('/'),
            filename.lastIndexOf('\\')
    );

    // An extension must be after the last separator
    if (lastSeparatorIdx > lastDotIdx) {
        return -1;
    }

    return lastDotIdx;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator > dotIndex) {
        return -1;
    }
    return dotIndex;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            return true;
        }
        long currentTime = System.currentTimeMillis();
        long elapsed = currentTime - timestamp;
        if (elapsed < 0) {
            return false;
        }
        return elapsed >= expiredThreshold;
    } catch (Exception e) {
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            // Non-positive threshold means never expire
            return false;
        }
        long currentTimeMillis = System.currentTimeMillis();
        // If timestamp is in the future, it cannot be expired
        if (timestamp > currentTimeMillis) {
            return false;
        }
        long elapsed = currentTimeMillis - timestamp;
        return elapsed >= expiredThreshold;
    } catch (Exception e) {
        // On any unexpected exception, assume not expired to avoid accidental removal
        return false;
    }
}

public boolean isExpired(long timestamp,long expiredThreshold){
    // Validate threshold
    if (expiredThreshold <= 0) {
        return false; // No valid threshold, cannot be considered expired
    }
    // Validate timestamp
    if (timestamp <= 0) {
        // If last update time is not set or invalid, treat as expired
        return true;
    }
    try {
        long currentTime = System.currentTimeMillis();
        long elapsed = currentTime - timestamp;
        return elapsed > expiredThreshold;
    } catch (Exception e) {
        // In case of unexpected error, assume not expired to avoid accidental eviction
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Return false immediately if threshold is non-positive, as nothing can expire.
    if (expiredThreshold <= 0) {
        return false;
    }

    try {
        long now = System.currentTimeMillis();
        // Use subtractExact to detect overflow.
        long age = Math.subtractExact(now, timestamp);
        // If timestamp is in the future, the metrics cannot be expired yet.
        if (age < 0) {
            return false;
        }
        return age >= expiredThreshold;
    } catch (ArithmeticException e) {
        // In case of overflow or other arithmetic issues, conservatively do not expire.
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (timestamp < 0) {
            throw new IllegalArgumentException("timestamp must be non-negative");
        }
        if (expiredThreshold < 0) {
            throw new IllegalArgumentException("expiredThreshold must be non-negative");
        }
        long currentTime = System.currentTimeMillis();
        long age = currentTime - timestamp;
        return age > expiredThreshold;
    } catch (Exception e) {
        // In the event of an unexpected exception, propagate as a runtime exception
        throw new RuntimeException("Failed to evaluate expiration", e);
    }
}

