}

protected void append(LoggingEvent event) {
    // Guard against null events
    if (event == null) {
        return;
    }

    // Convert the log event to a signed message string
    String message = event.getRenderedMessage();
    if (message == null) {
        message = "";
    }

    // Append a newline so that each message terminates on the client side
    message += System.lineSeparator();
    byte[] bytes = message.getBytes(java.nio.charset.StandardCharsets.UTF_8);

    // Iterate over the currently connected clients and send the message
    // If a client fails to receive the data, remove it from the list
    synchronized (clients) {
        java.util.Iterator<java.net.Socket> it = clients.iterator();
        while (it.hasNext()) {
            java.net.Socket socket = it.next();
            try {
                java.io.OutputStream out = socket.getOutputStream();
                out.write(bytes);
                out.flush();
            } catch (java.io.IOException ioEx) {
                // Client failed; close socket and remove from collection
                it.remove();
                try {
                    socket.close();
                } catch (java.io.IOException ignored) {
                }
            }
        }
    }
}

protected void append(LoggingEvent event){
    // Guard against null events since Apache Foundation typically passes non-null
    if (event == null) {
        return;
    }

    // Get the formatted message from the event. If null, nothing to send.
    String message = event.getRenderedMessage();
    if (message == null || message.isEmpty()) {
        return;
    }

    // The class is expected to maintain a collection of connected clients.
    // Because we don't know the exact type, we keep the reference generic
    // and only interact with components that provide a write-like capability.
    for (Object clientObj : clients) {
        if (clientObj == null) {
            continue;
        }
        try {
            // Preferred case: use a PrintWriter or something similar that
            // permits string output and a flush operation.
            if (clientObj instanceof PrintWriter) {
                PrintWriter pw = (PrintWriter) clientObj;
                pw.println(message);
                pw.flush();
            }
            // Alternative fallback: if the client implements a send or write method.
            else if (clientObj instanceof LogClient) {          // hypothetical interface
                ((LogClient) clientObj).send(message);
            }
            else if (clientObj instanceof java.io.Writer) {
                java.io.Writer w = (java.io.Writer) clientObj;
                w.write(message + System.lineSeparator());
                w.flush();
            }
            // If none of the above, we skip this client safely.
        } catch (Exception ex) {
            // Log the exception locally and continue with the next client.
            // Using System.err for simplicity; replace with your logger if available.
            System.err.println("Failed to deliver log message to a client: " + ex);
        }
    }
}

protected void append(LoggingEvent event) {
    // Guard against a null logging event
    if (event == null) {
        return;
    }

    // Extract the log message reliably
    String message;
    try {
        message = event.getRenderedMessage();
    } catch (Throwable t1) { // Fallback if getRenderedMessage isn't available
        try {
            message = event.toString();
        } catch (Throwable t2) {
            message = "";
        }
    }
    if (message == null) {
        message = "";
    }

    // If there are no clients connected, nothing to do
    if (clients == null || clients.isEmpty()) {
        return;
    }

    // Send the message to every connected client
    for (Object client : clients) {
        if (client == null) {
            continue;
        }
        try {
            java.lang.reflect.Method writeMethod = client.getClass().getMethod("write", String.class);
            writeMethod.invoke(client, message);
        } catch (Exception ignored) {
            // Ignore failures for individual clients to avoid breaking the entire loop
        }
    }
}

protected void append(LoggingEvent event) {
    if (event == null) {
        // Nothing to log
        return;
    }

    // Retrieve the rendered message from the event.  If the renderer fails, fall back to the
    // event's default string representation.
    String message;
    try {
        message = event.getRenderedMessage();
    } catch (Exception e) {
        message = event.toString();
    }

    if (message == null) {
        return;
    }

    // Take a snapshot of current connections to avoid ConcurrentModificationException
    Collection<ClientHandler> snapshot;
    synchronized (connections) {
        snapshot = Collections.unmodifiableCollection(new ArrayList<>(connections));
    }

    // Push the message to every connected client
    for (ClientHandler client : snapshot) {
        try {
            client.send(message);
        } catch (IOException ioEx) {
            // If sending fails, close the client and remove it from the active set
            try {
                client.close();
            } catch (IOException closeEx) {
                // ignore secondary failure
            }
            synchronized (connections) {
                connections.remove(client);
            }
        }
    }
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }

    String msg;
    try {
        // Try to get the fully rendered message.
        msg = event.getRenderedMessage();
    } catch (Exception e) {
        // Fallback if the method is not available.
        msg = event.toString();
    }

    if (msg == null) {
        msg = "";
    }

    // Append a line separator to mimic log output format.
    msg += System.lineSeparator();

    // Convert to bytes once for performance.
    byte[] data;
    try {
        data = msg.getBytes(java.nio.charset.StandardCharsets.UTF_8);
    } catch (Exception e) {
        // Very unlikely, but fallback.
        try {
            data = msg.getBytes("UTF-8");
        } catch (java.io.UnsupportedEncodingException ue) {
            data = msg.getBytes();
        }
    }

    // Iterate over connected clients and write the message.
    synchronized (clientWriters) {
        for (java.util.Iterator<java.io.Writer> it = clientWriters.iterator(); it.hasNext();) {
            java.io.Writer writer = it.next();
            try {
                writer.write(new java.lang.String(data, java.nio.charset.StandardCharsets.UTF_8));
                writer.flush();
            } catch (java.io.IOException e) {
                // If writing fails, remove this client and close the writer.
                it.remove();
                try {
                    writer.close();
                } catch (java.io.IOException ignored) { }
            }
        }
    }
}

