private void checkIfPackedField() throws IOException {
    // Ensure we have a valid tag to inspect. If no tag was read yet,
    // simply mark that we are not in a packed field and return.
    if (lastTag == 0) {
        this.isPackedField = false;
        return;
    }

    // Decode the field number and wire type from the tag.
    int fieldNumber = lastTag >>> 3;
    int wireType   = lastTag & 0x7;

    // A packed field can only occur if the field number matches the
    // number expected for packed repeated fields and the wire type is
    // LENGTH_DELIMITED (value 2 in the protobuf wire format).
    if (packedFieldNumber == fieldNumber && wireType == WIRETYPE_LENGTH_DELIMITED) {
        // We have entered a packed field: update state and read the
        // length prefix that bounds the packed data.
        this.isPackedField = true;
        int packedLength = readRawVarint32();
        // Push the new limit so that subsequent reads do not consume
        // bytes belonging to the packed field.
        pushLimit(packedLength);
    } else {
        // Not a packed field; clear the flag.
        this.isPackedField = false;
    }
}

private void checkIfPackedField() throws IOException {
    // Packed repeated fields use wire type LENGTH_DELIMITED.
    if (wireType != WIRETYPE_LENGTH_DELIMITED) {
        // Not a packed field, clear packed flag.
        packed = false;
        return;
    }
    // If the descriptor indicates a repeated primitive that can be packed, enter packed mode.
    if (fieldDescriptor != null && fieldDescriptor.isRepeated() && fieldDescriptor.isPackable()) {
        packed = true;
        // Read the length of the packed data.
        int packedLength = readRawVarint32();
        // Set a new limit for reading the packed values.
        oldLimit = limit;
        limit = pushLimit(packedLength);
    } else {
        // Not a packed field, keep packed flag false.
        packed = false;
    }
}

private void checkIfPackedField() throws IOException {
    // Ensure we have a valid current field to inspect
    int fieldNumber = this.currentFieldNumber;
    if (fieldNumber <= 0) {
        throw new IOException("Attempted to check packing for an invalid field number: " + fieldNumber);
    }

    // Retrieve the descriptor for the current field (assumes a map of descriptors is maintained)
    FieldDescriptor descriptor = this.fieldDescriptorMap.get(fieldNumber);
    if (descriptor == null) {
        throw new IOException("No descriptor found for field number: " + fieldNumber);
    }

    // Determine whether this field is a packed field per its descriptor
    boolean isPacked = descriptor.isPacked();

    if (isPacked) {
        // Packed fields in protobuf must be encoded with a length‑delimited wire type (wire type = 2)
        // If the current wire type is not length‑delimited, the stream is malformed
        if (this.currentWireType != WIRETYPE_LENGTH_DELIMITED) {
            throw new IOException("Packed field " + fieldNumber + " uses incorrect wire type: "
                    + this.currentWireType + " (expected length‑delimited).");
        }
        // Update the internal state to note that packed fields are being read
        this.packedFieldsInReading = true;
    } else {
        // If not a packed field, ensure we are not in packed‑reading mode
        this.packedFieldsInReading = false;
    }
}

private void checkIfPackedField() throws IOException {
    // If we were already processing a packed field but a new field number has been seen,
    // reset the packed state.
    if (packedFieldNumber != -1 && currentFieldNumber != packedFieldNumber) {
        packedFieldNumber = -1;
    }

    // If the current field uses the length-delimited wire type and the protocol
    // definition marks it as a packed field, we should start reading packed data.
    if (currentWireType == 2 && isPackedField(currentFieldNumber)) {
        packedFieldNumber = currentFieldNumber;
    }
}

private void checkIfPackedField() throws IOException {
    // Extract the wire type from the current field tag
    int wireType = fieldTag & 0x07;

    // If the field descriptor is available and the wire type indicates a
    // length-delimited field, check whether this field can be packed.
    if (fieldDescriptor != null &&
        wireType == 2 &&                  // WireFormat.WIRETYPE_LENGTH_DELIMITED
        fieldDescriptor.isRepeated() &&
        fieldDescriptor.isPacked()) {

        // Update internal state to reflect that we are now reading a packed field.
        packedField = true;

        // The packed representation starts with a varint length followed by the
        // raw bytes. Read this length, then set a limit on the input to avoid
        // reading past the end of the packed data.
        int packedLength = readRawVarint32(); // throws IOException if I/O error
        oldLimit = pushLimit(packedLength);   // throws IOException if a limit cannot be set
    }
