public int readTag() throws IOException {
    // Attempt to read the next field tag from the input.  Protocol
    // buffers use a varint encoding; if the end of the input stream has
    // been reached, we return zero as a sentinel value.  Any other
    // IOException is propagated upwards.
    try {
        return readRawVarint32();
    } catch (EOFException e) {
        // Reached end of file; return zero to signal no more tags.
        return 0;
    }
}

public int readTag() throws IOException {
    // Attempt to read the first byte, which may indicate EOF.
    int first = readRawByte();
    if (first == -1) { // EOF
        return 0;
    }

    // If the high bit is clear, the whole tag is contained in this byte.
    if ((first & 0x80) == 0) {
        return first;
    }

    // Build the varint manually; tags are at most 32-bit,
    // so we read up to 5 bytes.
    int result = first & 0x7F;
    int shift = 7;
    for (int i = 0; i < 4; i++) {
        int b = readRawByte();
        if (b == -1) {
            // Unexpected EOF while decoding varint
            throw new IOException("Unexpected end of input while parsing a varint");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }

    // If we get here, the varint is too long (more than 5 bytes for a tag).
    throw new IOException("Malformed varint while parsing tag");
}

public int readTag() throws IOException {
    try {
        return readRawVarint32();
    } catch (java.io.EOFException e) {
        // Reached EOF while attempting to read a tag
        return 0;
    }
}

public int readTag() throws IOException {
    if (isAtEnd()) {
        currentTag = 0;
        return 0;
    }
    currentTag = readRawVarint32();
    return currentTag;
}

