final ByteVector put11(final int byteValue1,final int byteValue2){
    // Validate input byte values (0-255)
    if(byteValue1 < 0 || byteValue1 > 0xFF)
        throw new IllegalArgumentException("byteValue1 must be in 0..255");
    if(byteValue2 < 0 || byteValue2 > 0xFF)
        throw new IllegalArgumentException("byteValue2 must be in 0..255");
    // Ensure there is enough capacity for two more bytes
    int required = this.length + 2;
    if(required > this.value.length){
        int newSize = Math.max(this.value.length * 2, required);
        byte[] newArray = new byte[newSize];
        System.arraycopy(this.value, 0, newArray, 0, this.length);
        this.value = newArray;
    }
    // Store the bytes
    this.value[this.length++] = (byte) byteValue1;
    this.value[this.length++] = (byte) byteValue2;
    return this;
}

